const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;display:flex;flex-direction:column;gap:6px;width:100%;height:100%;min-width:0;min-height:0;padding:10px;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.card *{box-sizing:border-box}\nbutton{font:inherit;color:inherit;cursor:pointer}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.top{flex:none;display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.ttl{display:flex;align-items:center;gap:6px;min-width:0}\n.ttl b{font-size:15px;white-space:nowrap}\n.ro{flex:none;font-size:10px;line-height:15px;padding:0 6px;border-radius:999px;border:1px solid var(--line);background:var(--soft);color:var(--muted)}\n.sum{flex:none;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.main{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.act{flex:none;display:flex;align-items:center;gap:8px;min-width:0}\n.go{flex:none;height:34px;padding:0 14px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:600;white-space:nowrap}\n.go:disabled{opacity:.6;cursor:default}\n.stat{display:flex;flex-direction:column;min-width:0;font-size:11px;color:var(--muted)}\n.stat b{color:var(--ink);font-size:12px}\n.stat b,.stat span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.body{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;overflow:hidden}\n.res{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.fl{flex:none;display:flex;gap:5px;overflow-x:auto;padding-bottom:2px}\n.fl.wrap{flex-wrap:wrap;overflow:visible}\n.chip{flex:none;white-space:nowrap;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);border-radius:999px;padding:3px 10px;line-height:1.3}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:5px;padding-right:2px}\n.list>*{flex:none}\n.note{padding:5px 8px;border-radius:8px;background:var(--soft);border:1px solid var(--line);color:var(--ink);font-size:11px;overflow-wrap:anywhere}\n.note.err{border-color:var(--ink);font-weight:600}\n.hint{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.short{display:none}\n.it{border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);overflow:hidden}\n.it-h{display:block;width:100%;min-width:0;text-align:left;border:0;background:transparent;padding:6px 8px}\n.sj{font-weight:600;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.it.open .sj{display:block;overflow:visible}\n.it.done .sj{opacity:.6}\n.mt{color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tg{display:inline-block;margin-right:4px;padding:0 5px;border-radius:4px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font-size:10px;font-weight:500;line-height:15px;vertical-align:1px}\n.tg.reply{border-color:var(--accent)}\n.tg.prepare{border-color:var(--accent-alt)}\n.tg.attend{border-style:dashed;border-color:var(--ink)}\n.dt{padding:2px 8px 8px;display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line)}\n.kv{display:grid;grid-template-columns:auto minmax(0,1fr);gap:3px 8px;font-size:11px;padding-top:6px}\n.k{color:var(--muted);white-space:nowrap}\n.v{overflow-wrap:anywhere;min-width:0}\n.dact{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.mini{border:1px solid var(--line);background:var(--button-paper);color:var(--ink);border-radius:8px;padding:4px 10px}\n.mini.prim{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600;align-self:flex-start}\n.frm{flex:1;min-height:0;min-width:0;overflow-y:auto;display:grid;grid-template-columns:minmax(0,1fr);gap:8px;align-content:start;padding-right:2px}\n.fd{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lb{font-weight:600;font-size:11px}\n.hn{color:var(--muted);font-size:10.5px;overflow-wrap:anywhere}\n.fd input{width:100%;min-width:0;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:5px 8px;font:inherit}\n.dates{display:flex;align-items:center;gap:6px;min-width:0}\n.dates input{flex:1}\n.frm>.note,.frm>.mini,.fd.wide{grid-column:1/-1}\n[data-size=\"3x3\"].card{padding:8px;gap:5px}\n[data-size=\"3x3\"] .sum,[data-size=\"3x3\"] .rng,[data-size=\"3x3\"] .long{display:none}\n[data-size=\"3x3\"] .short,[data-size=\"6x3\"] .short{display:inline}\n[data-size=\"6x3\"] .long{display:none}\n[data-size=\"3x3\"] .go{height:30px;padding:0 10px}\n[data-size=\"3x3\"] .ttl b{font-size:13px}\n[data-size=\"3x3\"] .note.cal{order:99}\n[data-size=\"6x3\"].card{padding:8px;gap:4px}\n[data-size=\"6x3\"] .sum{display:none}\n[data-size=\"6x3\"] .main{flex-direction:row;gap:8px}\n[data-size=\"6x3\"] .act{flex-direction:column;align-items:stretch;width:118px;gap:6px}\n[data-size=\"6x3\"] .go{width:100%}\n[data-size=\"6x3\"] .body{flex:1}\n[data-size=\"6x3\"] .hint.rng{display:none}\n[data-size=\"6x3\"] .frm{grid-template-columns:repeat(2,minmax(0,1fr))}\n[data-size=\"6x6\"].card{padding:14px;gap:8px;font-size:13px}\n[data-size=\"6x6\"] .ttl b{font-size:17px}\n[data-size=\"6x6\"] .frm{grid-template-columns:repeat(2,minmax(0,1fr))}\n[data-size=\"3x6\"] .stat span{white-space:normal}\n.xl{font-style:normal}\n[data-size=\"3x3\"] .xl,[data-size=\"6x3\"] .xl{display:none}\n";
var RULES=[
{k:'attend',w:['会议','开会','邀请','日程','参加','出席','面试','培训','评审','例会','研讨','直播','meeting','invite','invitation','webinar','calendar','rsvp']},
{k:'prepare',w:['准备','材料','提交','截止','到期','期限','deadline','due','汇报','报告','资料','审批','填写','签署','请补充','prepare','submit','please review','action required']},
{k:'reply',w:['请回复','回复','答复','请确认','反馈','意见','请问','是否','能否','麻烦','尽快','reply','respond','confirm','feedback','urgent','asap','?','？']}
];
var TAGN={reply:'回复',prepare:'准备',attend:'参加'};
var PRESETS={today:1,'3':3,'7':7,'30':30};
var PLABEL={today:'今天','3':'近3天','7':'近7天','30':'近30天',custom:'自定义'};
function pick(o,ks){for(var i=0;i<ks.length;i++){var v=o[ks[i]];if(v!==undefined&&v!==null&&v!=='')return v}return ''}
function txt(v){
  if(v===undefined||v===null)return '';
  if(typeof v==='string')return v;
  if(typeof v==='number')return String(v);
  if(Array.isArray(v))return v.map(txt).filter(Boolean).join('、');
  if(typeof v==='object'){var n=txt(pick(v,['name','displayName'])),a=txt(pick(v,['address','email','value']));return n&&a&&n!==a?n+' <'+a+'>':(n||a)}
  return ''
}
function toMs(v){
  if(v===undefined||v===null||v==='')return 0;
  if(typeof v==='number')return v<1e11?v*1000:v;
  if(/^\d{10,13}$/.test(String(v))){var n=Number(v);return n<1e11?n*1000:n}
  var t=Date.parse(v);return isNaN(t)?0:t
}
function pad(n){return n<10?'0'+n:''+n}
function dstr(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function addDays(ds,n){var p=ds.split('-');return dstr(new Date(+p[0],+p[1]-1,+p[2]+n))}
function dayStart(ds){var p=ds.split('-');return new Date(+p[0],+p[1]-1,+p[2]).getTime()}
function fmt(ms){var d=new Date(ms);return pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes())}
function fmtFull(ms){var d=new Date(ms);return d.getFullYear()+'-'+fmt(ms)}
function rangeOf(c,today){
  if(c.preset==='custom'&&c.from&&c.to)return {from:c.from,to:c.to};
  var n=PRESETS[c.preset]||7;
  return {from:addDays(today,1-n),to:today}
}
function listOf(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){
    var ks=['messages','items','list','records','mails','results','data'];
    for(var i=0;i<ks.length;i++){if(Array.isArray(d[ks[i]]))return d[ks[i]]}
  }
  return null
}
function normMsg(m,i){
  m=m&&typeof m==='object'?m:{};
  var time=toMs(pick(m,['date','receivedAt','received_at','receivedDate','receivedDateTime','sentAt','sent_at','internalDate','timestamp','time','createdAt']));
  return {
    id:txt(pick(m,['id','messageId','message_id','uid','mid']))||('#'+i+'-'+time),
    subject:txt(pick(m,['subject','Subject','title'])),
    from:txt(pick(m,['from','sender','fromName','from_name','fromAddress','from_address'])),
    to:txt(pick(m,['to','recipients','toAddress','to_address'])),
    time:time,
    unread:m.unread===true||m.isRead===false||m.is_read===false||m.seen===false||m.read===false,
    acct:txt(pick(m,['account','accountEmail','account_email','mailAccount','owner','email'])),
    folder:txt(pick(m,['folder','mailbox','label'])),
    snippet:txt(pick(m,['snippet','preview','summary','bodyPreview','body_preview','excerpt'])).slice(0,140)
  }
}
function classify(m){
  var hay=((m.subject||'')+' '+(m.snippet||'')).toLowerCase(),tags=[],words=[];
  RULES.forEach(function(r){
    var f=r.w.filter(function(w){return hay.indexOf(w)>=0});
    if(f.length){tags.push(r.k);f.forEach(function(w){if(words.indexOf(w)<0)words.push(w)})}
  });
  return {tags:tags,words:words.slice(0,5)}
}
async function scanMail(c,today,fetchSource){
  var raw=await fetchSource('connected.mail.message-list');
  var arr=listOf(raw);
  if(!arr)throw new Error('邮件数据格式无法识别');
  var r=rangeOf(c,today),a=dayStart(r.from),b=dayStart(addDays(r.to,1))-1;
  var list=arr.map(normMsg),note='',want=(c.mailbox||'').trim().toLowerCase();
  if(want){
    if(list.some(function(m){return m.acct}))list=list.filter(function(m){return m.acct.toLowerCase().indexOf(want)>=0});
    else note='邮件数据没有带邮箱字段，未能按所填邮箱筛选，显示的是平台已连接邮箱的全部邮件。'
  }
  var noDate=0,hits=[],rest=[];
  list.forEach(function(m){
    if(!m.time){noDate++;return}
    if(m.time<a||m.time>b)return;
    var k=classify(m);m.tags=k.tags;m.words=k.words;
    (k.tags.length?hits:rest).push(m)
  });
  var byTime=function(x,y){return y.time-x.time};
  hits.sort(byTime);rest.sort(byTime);
  var inRange=hits.length+rest.length,MAXN=400;
  hits=hits.slice(0,MAXN);
  rest=rest.slice(0,Math.max(0,MAXN-hits.length));
  return {at:Date.now(),from:r.from,to:r.to,mailbox:c.mailbox||'',total:arr.length,inRange:inRange,noDate:noDate,note:note,cut:inRange-hits.length-rest.length,hits:hits,rest:rest}
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,day,runAsync,fetchSource}=ctx;
  const s=state||{};
  const cfg=Object.assign({mailbox:'',calendar:'',preset:'7',from:'',to:''},s.cfg||{});
  const snap=s.snap||null;
  const checked=s.checked||{};
  if(!ui.draft)ui.draft={};
  if(!ui.f)ui.f='all';
  const A=(...x)=>x.filter(Boolean);
  const job=(ui.jobs||{})[ui.cur];
  const loading=!!(job&&job.status==='loading');

  function effCfg(){return Object.assign({},cfg,ui.draft)}
  function badRange(e){
    if(e.preset!=='custom')return '';
    if(!e.from||!e.to)return '请选择起止日期';
    if(e.from>e.to)return '起始日期晚于结束日期';
    return '';
  }
  function saveCfg(patch){
    const next=Object.assign({},effCfg(),patch||{});
    ui.draft={};
    return update(st=>Object.assign({},st,{cfg:next})).catch(()=>false);
  }
  function setPreset(p){
    const e=effCfg();
    const patch={preset:p};
    if(p==='custom'&&(!e.from||!e.to)){const r=rangeOf(e,day());patch.from=r.from;patch.to=r.to}
    ui.formErr='';
    saveCfg(patch);
  }
  function toggleCfg(){
    if(ui.cfgOpen){
      const err=badRange(effCfg());
      if(err){ui.formErr=err;redraw();return}
      ui.formErr='';ui.cfgOpen=false;saveCfg();
    }else{ui.cfgOpen=true;redraw()}
  }
  function onScan(){
    const e=effCfg();
    const err=badRange(e);
    if(err){ui.formErr=err;ui.cfgOpen=true;redraw();return}
    ui.formErr='';
    ui.seq=(ui.seq||0)+1;
    const key='scan'+ui.seq;
    ui.cur=key;ui.f='all';ui.open='';
    saveCfg();
    runAsync(key,()=>scanMail(e,day(),fetchSource)).then(function(ok){
      const j=(ui.jobs||{})[key];
      if(ok&&j&&j.data){update(st=>Object.assign({},st,{snap:j.data})).catch(()=>false)}
    });
  }
  function toggleCheck(id){
    update(st=>{
      const c=Object.assign({},st.checked||{});
      if(c[id])delete c[id];else c[id]=true;
      return Object.assign({},st,{checked:c});
    }).catch(()=>false);
  }
  function toggleOpen(id){ui.open=ui.open===id?'':id;redraw()}
  function setF(f){ui.f=f;ui.open='';redraw()}


  function field(label,input,hint){
    return el('label',{class:'fd'},...A(el('span',{class:'lb'},label),input,hint?el('span',{class:'hn'},hint):null));
  }
  function form(){
    const e=effCfg();
    const rng=rangeOf(e,day());
    const presets=['today','3','7','30','custom'].map(p=>el('button',{type:'button',class:'chip'+(e.preset===p?' on':''),'aria-pressed':String(e.preset===p),onclick:()=>setPreset(p)},PLABEL[p]));
    const custom=e.preset==='custom'?el('div',{class:'dates'},
      el('input',{type:'date',value:e.from||rng.from,'aria-label':'起始日期',oninput:ev=>{ui.draft.from=ev.target.value}}),
      el('span',{},'至'),
      el('input',{type:'date',value:e.to||rng.to,'aria-label':'结束日期',oninput:ev=>{ui.draft.to=ev.target.value}})):null;
    return el('div',{class:'frm'},...A(
      field('邮箱',el('input',{type:'text',value:e.mailbox,placeholder:'地址或名称，留空＝全部已连接邮箱',oninput:ev=>{ui.draft.mailbox=ev.target.value}}),'邮件来自平台已连接的邮箱；邮件带有账号信息时才能按这里筛选。'),
      field('日历',el('input',{type:'text',value:e.calendar,placeholder:'日历名称',oninput:ev=>{ui.draft.calendar=ev.target.value}}),'日历读取暂未接入，这里只保存你的选择。'),
      el('div',{class:'fd wide'},...A(el('span',{class:'lb'},'日期范围'),el('div',{class:'fl wrap'},...presets),custom,
        el('span',{class:'hn'},'当前：'+rng.from+' 至 '+rng.to))),
      ui.formErr?el('div',{class:'note err'},'⚠ '+ui.formErr):null,
      el('div',{class:'note'},'只读：只读取并标注，不会回复、归档、删除邮件，也不会改动日程。'),
      el('button',{type:'button',class:'mini prim',onclick:toggleCfg},'完成')
    ));
  }

  function detail(m){
    const rows=[['发件人',m.from],['收件人',m.to],['时间',m.time?fmtFull(m.time):''],['账号',m.acct],['文件夹',m.folder],['摘要',m.snippet],['命中',m.words&&m.words.length?m.words.join('、'):'没有命中规则'],['邮件ID',m.id]].filter(r=>r[1]);
    const kids=[];
    rows.forEach(r=>{kids.push(el('span',{class:'k'},r[0]));kids.push(el('span',{class:'v'},String(r[1])))});
    const done=!!checked[m.id];
    return el('div',{class:'dt'},
      el('div',{class:'kv'},...kids),
      el('div',{class:'dact'},
        el('button',{type:'button',class:'mini',onclick:()=>toggleCheck(m.id)},done?'取消核对标记':'标记为已核对'),
        el('span',{class:'hn'},'仅记在本卡片，不改动邮件')));
  }
  function row(m){
    const open=ui.open===m.id,done=!!checked[m.id];
    const tags=(m.tags||[]).map(t=>el('span',{class:'tg '+t},TAGN[t]));
    if(m.unread)tags.push(el('span',{class:'tg'},'未读'));
    if(done)tags.push(el('span',{class:'tg'},'已核对'));
    return el('div',{class:'it'+(open?' open':'')+(done?' done':'')},...A(
      el('button',{type:'button',class:'it-h','aria-expanded':String(open),onclick:()=>toggleOpen(m.id)},
        el('div',{class:'sj'},...tags,m.subject||'（无主题）'),
        el('div',{class:'mt'},(m.from||'未知发件人')+' · '+(m.time?fmt(m.time):'无日期'))),
      open?detail(m):null));
  }
  function results(){
    const notes=[];
    if(job&&job.status==='error'){
      notes.push(el('div',{class:'note err'},'⚠ 未能读取邮件：'+(job.error&&job.error.message?job.error.message:(job.error||'未知错误'))+'。'+(snap?'已保留上次结果。':'')+'若还没连接邮箱，请先在平台连接后再试。'));
    }
    notes.push(el('div',{class:'note cal'},
      el('span',{class:'long'},'日历'+(cfg.calendar?'「'+cfg.calendar+'」':'')+'暂未接入：平台还不能读取日程，这次只查了邮件，日程请自行查看。'),
      el('span',{class:'short'},'日历未接入，日程未查')));
    if(!snap){
      notes.push(el('div',{class:'hint'},'选好邮箱、日历和日期范围后点「找出事项」。结果逐条带上对应邮件，方便你核对。'));
      return el('div',{class:'res'},el('div',{class:'list'},...notes));
    }
    notes.push(el('div',{class:'hint rng'},'范围 '+snap.from+' 至 '+snap.to+(snap.mailbox?' · 邮箱 '+snap.mailbox:'')+'；按主题与摘要里的关键词判断，非智能识别，请核对。'));
    if(snap.note)notes.push(el('div',{class:'note'},snap.note));
    if(snap.noDate)notes.push(el('div',{class:'note'},snap.noDate+' 封邮件缺少日期，未纳入。'));
    if(snap.cut>0)notes.push(el('div',{class:'note'},'另有 '+snap.cut+' 封超出保存上限，未显示。'));
    const hits=snap.hits||[],rest=snap.rest||[];
    const cnt=k=>hits.filter(m=>(m.tags||[]).indexOf(k)>=0).length;
    const defs=[['all','全部 '+hits.length],['reply','回复 '+cnt('reply')],['prepare','准备 '+cnt('prepare')],['attend','参加 '+cnt('attend')],['rest','未命中 '+rest.length]];
    const chips=defs.map(d=>el('button',{type:'button',class:'chip'+(ui.f===d[0]?' on':''),'aria-pressed':String(ui.f===d[0]),onclick:()=>setF(d[0])},d[1]));
    let items;
    if(ui.f==='rest')items=rest;
    else if(ui.f==='all')items=hits;
    else items=hits.filter(m=>(m.tags||[]).indexOf(ui.f)>=0);
    const body=items.length?items.map(row):[el('div',{class:'hint'},ui.f==='rest'?'没有其他邮件。':'这个范围内没有命中规则的邮件，可以看看「未命中」确认没有漏掉。')];
    return el('div',{class:'res'},el('div',{class:'fl'},...chips),el('div',{class:'list'},...notes,...body));
  }
  function statLines(){
    if(loading)return [el('b',{},'读取中…'),el('span',{},'正在读取邮件')];
    if(snap)return [el('b',{},'待跟进 '+(snap.hits||[]).length+' 件'),el('span',{},el('i',{class:'xl'},'邮件 '+snap.inRange+' 封 · '),fmt(snap.at))];
    return [el('b',{},'尚未查询'),el('span',{},'点按钮开始')];
